# Initially generated by GitHub Copilot.
"""Helpers for verifying special ketiv/qere subtype word and atom counts."""

import re
from collections import defaultdict

from author_util.claim import ClaimRecord
from mb_cmn import hebrew_punctuation as hpu
from verify_mp.corpus import Context, iter_all_template_objects

_Q2_TO_G2 = str.maketrans({'"': hpu.GERSHAYIM})
_WORD_SPLIT = re.compile(rf"[\s{hpu.MAQ}]+")


def verify(record: ClaimRecord, ctx: Context) -> None:
    """Verify per-subtype word counts and allowed atom-count pairs."""
    tmpl_name = record.data["template"]
    param_name = record.data["param"]
    expected_by_subtype = record.data["subtype_counts"]

    observed_word_pairs = defaultdict(set)
    observed_atom_pairs = defaultdict(set)

    for tmpl in iter_all_template_objects(ctx.corpus):
        if tmpl["tmpl_name"] != tmpl_name:
            continue
        params = tmpl.get("tmpl_params", {})
        subtype = _normalize_named_param(params.get(param_name))
        assert subtype in expected_by_subtype, subtype

        ketiv_raw = params.get("1")
        qere_raw = params.get("2")
        assert ketiv_raw is not None, tmpl
        assert qere_raw is not None, tmpl

        word_pair = (_count_words(ketiv_raw), _count_words(qere_raw))
        atom_pair = (_count_atoms(ketiv_raw), _count_atoms(qere_raw))
        observed_word_pairs[subtype].add(word_pair)
        observed_atom_pairs[subtype].add(atom_pair)

    for subtype, spec in expected_by_subtype.items():
        assert subtype in observed_word_pairs, f"subtype not observed: {subtype}"
        expected_word_pair = {(spec["ketiv_words"], spec["qere_words"])}
        expected_atom_pairs = {tuple(pair) for pair in spec["atom_pairs"]}
        assert observed_word_pairs[subtype] == expected_word_pair, (
            subtype,
            sorted(observed_word_pairs[subtype]),
            sorted(expected_word_pair),
        )
        assert observed_atom_pairs[subtype] == expected_atom_pairs, (
            subtype,
            sorted(observed_atom_pairs[subtype]),
            sorted(expected_atom_pairs),
        )


def _normalize_named_param(raw):
    if isinstance(raw, str):
        return raw.translate(_Q2_TO_G2)
    if isinstance(raw, list) and len(raw) == 1 and isinstance(raw[0], str):
        return raw[0].translate(_Q2_TO_G2)
    assert False, raw


def _count_atoms(raw):
    return sum(
        _split_count(piece, atom_mode=True) for piece in _iter_param_strings(raw)
    )


def _count_words(raw):
    return sum(
        _split_count(piece, atom_mode=False) for piece in _iter_param_strings(raw)
    )


def _iter_param_strings(raw):
    if isinstance(raw, str):
        yield raw
        return
    if isinstance(raw, list):
        for item in raw:
            if isinstance(item, str):
                yield item
            elif isinstance(item, dict):
                continue
            else:
                assert False, item
        return
    assert False, raw


def _split_count(piece: str, *, atom_mode: bool) -> int:
    if atom_mode:
        return len([tok for tok in piece.split() if tok])
    return len([tok for tok in _WORD_SPLIT.split(piece) if tok])
